import { z } from 'zod';
import { resourceRoutes } from '@/features/auth/api/resource-routes';
import { resourceExportRoute } from '@/features/auth/api/resource-transfer';
import { productReviewsResource } from '../resource';
import type { ProductReview } from '../types';

/**
 * Product reviews BFF routes → NestJS /product-reviews. Bodies are bounded here; the
 * backend validates business rules and applies the maker–checker policy.
 */
const createBody = z.object({
  // Generated by the server when absent.
  reference: z.string().trim().max(160).optional(),
  productSlug: z.string().trim().max(160),
  rating: z.number().int(),
  title: z.string().trim().max(160).nullish(),
  body: z.string().trim().max(2000),
  reviewerName: z.string().trim().max(160),
  reviewerRole: z.string().trim().max(160).nullish(),
  reviewerEmail: z.string().trim().max(160),
  status: z.string().trim().max(160),
  reply: z.string().trim().max(2000).nullish(),
});
const updateBody = z.object({
  version: z.number().int().min(1),
  reference: z.string().trim().max(160).nullish(),
  productSlug: z.string().trim().max(160).nullish(),
  rating: z.number().int().nullish(),
  title: z.string().trim().max(160).nullish(),
  body: z.string().trim().max(2000).nullish(),
  reviewerName: z.string().trim().max(160).nullish(),
  reviewerRole: z.string().trim().max(160).nullish(),
  reviewerEmail: z.string().trim().max(160).nullish(),
  status: z.string().trim().max(160).nullish(),
  reply: z.string().trim().max(2000).nullish(),
});

export const { list, get, create, update, remove } = resourceRoutes<ProductReview>(
  productReviewsResource,
  {
    access: {
      read: 'product-reviews:read',
      create: 'product-reviews:create',
      update: 'product-reviews:update',
      delete: 'product-reviews:delete',
    },
    schemas: { create: createBody, update: updateBody },
  },
);

export const exportRoute = resourceExportRoute<ProductReview>(productReviewsResource, {
  access: 'product-reviews:read',
  fileName: 'product-reviews',
  columns: [
    { id: 'reference', header: 'productReviews.fields.reference', value: (e) => e.reference },
    { id: 'productSlug', header: 'productReviews.fields.productSlug', value: (e) => e.productSlug },
    { id: 'rating', header: 'productReviews.fields.rating', value: (e) => e.rating },
    { id: 'title', header: 'productReviews.fields.title', value: (e) => e.title },
    {
      id: 'reviewerName',
      header: 'productReviews.fields.reviewerName',
      value: (e) => e.reviewerName,
    },
    {
      id: 'reviewerRole',
      header: 'productReviews.fields.reviewerRole',
      value: (e) => e.reviewerRole,
    },
    {
      id: 'reviewerEmail',
      header: 'productReviews.fields.reviewerEmail',
      value: (e) => e.reviewerEmail,
    },
    { id: 'status', header: 'productReviews.fields.status', value: (e) => e.status },
    { id: 'updatedAt', header: 'productReviews.columns.updated', value: (e) => e.updatedAt },
  ],
});
